// 程序说明：图书管理系统 - 图书类

#ifndef BOOK_HPP
#define BOOK_HPP

#include <string>

using std::string;

// 图书类：记录图书编号、书名、库存数量
class Book {
public:
    Book() : id(""), name(""), stock(0) {}
    Book(const string& bookId, const string& bookName, int bookStock)
        : id(bookId), name(bookName), stock(bookStock) {}

    // 获取图书编号
    string getId() const { return id; }
    // 获取书名
    string getName() const { return name; }
    // 获取库存数量
    int getStock() const { return stock; }

    // 入库：库存增加 count 本
    void inStock(int count) { stock += count; }

    // 出库：库存减少 count 本，若数量不足返回 false
    bool outStock(int count) {
        if (count < 0 || count > stock) return false;
        stock -= count;
        return true;
    }

    // 借阅：库存减少 1 本，若无库存返回 false
    bool borrowOne() { return outStock(1); }

    // 归还：库存增加 1 本
    void returnOne() { inStock(1); }

    // 显示图书信息
    void print() const {
        std::cout << "编号: " << id
                  << " | 书名: " << name
                  << " | 库存: " << stock << std::endl;
    }

private:
    string id;    // 图书编号
    string name;  // 书名
    int stock;    // 当前库存数量
};

#endif // BOOK_HPP
